SENT = re.compile(r"[^.!?]*[.!?]+|[^.!?]+$")
results = {}
for name, text in TESTS.items():
    sents = [s.strip() for s in SENT.findall(text) if len(re.sub(r"[\s.!?]", "", s)) >= 2]
    results[name] = measure(name, sents)

(OUT / "test_outputs_metrics_v3.json").write_text(
    json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")

print(f"{'piece':28} {'평균':>5} {'>=60%':>5} {'<=15%':>5} {'우리/10k':>7}")
for name, m in results.items():
    tr = {k: v['count'] for k, v in m['transitions'].items() if v['count']}
    print(f"{name:28} {m['sent_len_chars']['mean']:5.1f} "
          f"{m['sent_len_chars']['long_ge60']:5.1f} {m['sent_len_chars']['short_le15']:5.1f} "
          f"{m['reader_terms_per10k']['우리']:7.1f}  전환어:{tr}")
